import { NewOfferPage } from './../../places/offers/new-offer/new-offer.page';
import { BookingsService } from './../bookings.service';
/* eslint-disable object-shorthand */

import { EventEmitter, Input, ViewChild } from '@angular/core';
import { Component, OnInit } from '@angular/core';
import { environment } from 'src/environments/environment';
import * as mapboxgl from '../../../../node_modules/mapbox-gl';
import * as MapboxGeocoder from '@mapbox/mapbox-gl-geocoder';
import { ModalController } from '@ionic/angular';
import { take, tap } from 'rxjs/operators';
import { Maps } from './maps.model';
import { Router } from '@angular/router';
@Component({
  selector: 'app-map',
  templateUrl: './map.page.html',
  styleUrls: ['./map.page.scss'],
})
export class MapPage implements OnInit {
  @Input() newOffer: NewOfferPage;
  public map: mapboxgl.Map;
  public location: string[];
  constructor(private bookingsService: BookingsService, private router: Router) {}

  ngOnInit() {

    this.map = new mapboxgl.Map({
      container: 'map',
      accessToken: environment.MAPBOX_DOWNLOADS_TOKEN,
      center: [-74.5, 40],
      style: 'mapbox://styles/mapbox/streets-v11',
      zoom: 9,
    });

    this.map.addControl(
      new MapboxGeocoder({
        accessToken: environment.MAPBOX_DOWNLOADS_TOKEN,
        mapboxgl: mapboxgl,
        reverseGeocode: true,
      })
    );
  }
  public closeModal()
  {

  }
  public getDetails(event) {
    this.map.on('click', (e) => {
      this.location =Object.values(e.lngLat);
      this.bookingsService.getAddress(this.location).subscribe();

    });
  }
}



